#[cfg(test)]
mod confirm_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_confirm_codec() {
        let original = Confirm {
            pbu: "a".repeat(8),
            set_id: 123456,
            report_index: 123456789,
            biz_id: 123456,
            exec_type: "a".to_string(),
            biz_pbu: "a".repeat(8),
            cl_ord_id: "a".repeat(10),
            security_id: "a".repeat(12),
            account: "a".repeat(13),
            owner_type: 42,
            side: "a".to_string(),
            price: -123456789,
            order_qty: -123456789,
            leaves_qty: -123456789,
            cxl_qty: -123456789,
            ord_type: "a".to_string(),
            time_in_force: "a".to_string(),
            ord_status: "a".to_string(),
            credit_tag: "a".repeat(2),
            orig_cl_ord_id: "a".repeat(10),
            clearing_firm: "a".repeat(8),
            branch_id: "a".repeat(8),
            ord_rej_reason: 123456,
            ord_cnfm_id: "a".repeat(16),
            orig_ord_cnfm_id: "a".repeat(16),
            trade_date: 123456,
            transact_time: 123456789,
            user_info: "a".repeat(32),
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let mut bytes = buf.freeze();

        let decoded = Confirm::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
    }
}
